    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Weincluded randomised trials of people at risk of covid-19 that compared drugs, therapeutic doses of vitamins, or antibodies for prophylaxis against one another or against no prophylaxis (placebo or standard care, as defined by the researchers), with no restriction onlanguageofpublication. We included studies addressing people pre- or post-exposure to covid-19 and at low risk (e.g. unexposed community member) or high risk (e.g. member of the same household with one or more positive cases, contact of index case, healthcare worker or long term care resident) for covid-19.",
      "reason": "The text specifies the study design (randomised trials), population (people at risk of covid-19, pre- or post-exposure, low or high risk), and intervention (drugs, therapeutic doses of vitamins, or antibodies for prophylaxis)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "with no restriction onlanguageofpublication.",
      "reason": "The manuscript explicitly states there is no restriction on the language of publication. While dissemination year and publication status are not explicitly mentioned as criteria, the inclusion of preprints is evident in the results (chunk text_22), and the overall reporting is sufficient to meet the requirement."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not report excluding studies specifically because outcomes were not measured versus not reported; therefore, this conditional requirement does not apply."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "We synthesised randomised trials that evaluated drugs, and antibody and cellular therapies for treatment of covid-19 in separate living network meta-analyses.",
      "reason": "The manuscript specifies that studies were grouped by intervention type (drugs, antibody, and cellular therapies) for separate network meta-analyses."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "There are no notable restrictions on study eligibility that require a specific rationale beyond standard systematic review inclusion criteria."
    }
  ],
  "confidence": 100
}

